import {
  Outlet,
  createRootRouteWithContext,
  createRoute,
  createRouter,
  lazyRouteComponent,
  redirect,
} from "@tanstack/react-router";

import type { AuthState } from "@/app/providers";
import { AdminErrorState } from "@/shared/components/states/admin-error-state";
import { AdminApiError } from "@/shared/api/transport";

export interface RouterContext {
  auth: AuthState;
}

export interface SpaceSearch {
  cursor?: string;
  q?: string;
  service?: string;
  status?: string;
}

export interface SpacesSearch {
  service?: string;
}

export interface AccountSearch {
  auth?: string;
  availability?: string;
  columns?: string;
  createdFrom?: string;
  createdTo?: string;
  cursor?: string;
  eligible?: "false" | "true";
  factor?: string;
  factorState?: string;
  hasOverride?: "false" | "true";
  lastLeasedFrom?: string;
  lastLeasedTo?: string;
  leased?: "false" | "true";
  lifecycle?: string;
  linked?: "false" | "true";
  proxy?: string;
  q?: string;
  requirement?: string;
  service?: string;
  standing?: string;
  standingChangedFrom?: string;
  standingChangedTo?: string;
  status?: string;
  syncedFrom?: string;
  syncedTo?: string;
  tag?: string;
  tier?: string;
}

export function parseSpaceSearch(search: Record<string, unknown>): SpaceSearch {
  const stringValue = (key: keyof SpaceSearch) =>
    typeof search[key] === "string" && search[key] !== ""
      ? search[key]
      : undefined;
  const cursor = stringValue("cursor");
  const q = stringValue("q");
  const service = stringValue("service");
  const status = stringValue("status");
  return {
    ...(cursor === undefined ? {} : { cursor }),
    ...(q === undefined ? {} : { q }),
    ...(service === undefined ? {} : { service }),
    ...(status === undefined ? {} : { status }),
  };
}

export function parseSpacesSearch(
  search: Record<string, unknown>,
): SpacesSearch {
  return typeof search.service === "string" && search.service !== ""
    ? { service: search.service }
    : {};
}

export function parseAccountSearch(
  search: Record<string, unknown>,
): AccountSearch {
  const result: Record<string, string> = {};
  const keys: Array<keyof AccountSearch> = [
    "auth",
    "availability",
    "columns",
    "createdFrom",
    "createdTo",
    "cursor",
    "eligible",
    "factor",
    "factorState",
    "hasOverride",
    "lastLeasedFrom",
    "lastLeasedTo",
    "leased",
    "lifecycle",
    "linked",
    "proxy",
    "q",
    "requirement",
    "service",
    "standing",
    "standingChangedFrom",
    "standingChangedTo",
    "status",
    "syncedFrom",
    "syncedTo",
    "tag",
    "tier",
  ];
  for (const key of keys) {
    const value = search[key];
    if (typeof value === "string" && value !== "") result[key] = value;
  }
  for (const key of ["eligible", "leased", "hasOverride", "linked"] as const) {
    if (result[key] !== "true" && result[key] !== "false") delete result[key];
  }
  return result as AccountSearch;
}

function safeRedirect(value: unknown): string {
  return typeof value === "string" &&
    value.startsWith("/") &&
    !value.startsWith("//")
    ? value
    : "/";
}

const rootRoute = createRootRouteWithContext<RouterContext>()({
  component: Outlet,
  errorComponent: ({ error, reset }) => (
    <AdminErrorState error={error} onRetry={reset} />
  ),
  notFoundComponent: () => (
    <AdminErrorState
      error={
        new AdminApiError(404, {
          error: {
            code: "not_found",
            message: "Страница не найдена",
            request_id: "router-not-found",
          },
        })
      }
    />
  ),
});

const designRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/_design",
  component: lazyRouteComponent(() => import("@/pages/design"), "DesignPage"),
});

const loginRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/login",
  validateSearch: (search) => ({ redirect: safeRedirect(search.redirect) }),
  component: lazyRouteComponent(() => import("@/pages/login"), "LoginPage"),
});

const authenticatedRoute = createRoute({
  getParentRoute: () => rootRoute,
  id: "_authenticated",
  beforeLoad: ({ context, location }) => {
    if (context.auth.principal === null) {
      throw redirect({ to: "/login", search: { redirect: location.href } });
    }
  },
  component: lazyRouteComponent(
    () => import("@/app/shell/app-shell"),
    "AppShell",
  ),
});

const overviewRoute = createRoute({
  getParentRoute: () => authenticatedRoute,
  path: "/",
  component: lazyRouteComponent(() => import("@/pages/home"), "HomePage"),
});

const spacesRoute = createRoute({
  getParentRoute: () => authenticatedRoute,
  path: "/spaces",
  validateSearch: parseSpacesSearch,
  component: lazyRouteComponent(() => import("@/pages/spaces"), "SpacesPage"),
});

const spaceRoute = createRoute({
  getParentRoute: () => authenticatedRoute,
  path: "/spaces/$spaceSlug",
  validateSearch: parseSpaceSearch,
  component: lazyRouteComponent(
    () => import("@/pages/space-overview"),
    "SpaceOverviewPage",
  ),
});

const accountsRoute = createRoute({
  getParentRoute: () => authenticatedRoute,
  path: "/spaces/$spaceSlug/accounts",
  validateSearch: parseAccountSearch,
  component: lazyRouteComponent(
    () => import("@/pages/accounts"),
    "AccountsPage",
  ),
});

const routeTree = rootRoute.addChildren([
  designRoute,
  loginRoute,
  authenticatedRoute.addChildren([
    overviewRoute,
    spacesRoute,
    accountsRoute,
    spaceRoute,
  ]),
]);

export const router = createRouter({
  routeTree,
  context: { auth: { error: null, isPending: true, principal: null } },
  defaultPreload: "intent",
  scrollRestoration: true,
});

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}

import { useMemo, useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useNavigate, useParams, useSearch } from "@tanstack/react-router";
import type { ColumnDef } from "@tanstack/react-table";

import { usePreferences } from "@/app/providers";
import type { AccountSearch } from "@/app/router";
import {
  AUTH_STATE_VIEW,
  AVAILABILITY_VIEW,
  DomainStatusBadge,
  LIFECYCLE_VIEW,
  STANDING_VIEW,
} from "@/entities/status/status";
import { fetchAccounts, type AccountQuery } from "@/shared/api/accounts";
import type {
  AccountListItemResponse,
  AccountPageResponse,
} from "@/shared/api/generated/types.gen";
import { fetchSpaceOverview } from "@/shared/api/overview";
import { POLL_INTERVAL } from "@/shared/api/query-client";
import {
  AccountColumnPicker,
  AccountFilters,
  type AccountFilterValue,
} from "@/shared/components/accounts/account-controls";
import {
  AccountListSummary,
  DateCell,
  EligibilityCell,
  LeaseCell,
  ProxyCell,
  TagsCell,
} from "@/shared/components/accounts/account-cells";
import { DataTable } from "@/shared/components/data-table/data-table";
import { QueryState } from "@/shared/components/states/query-state";
import { ListPage } from "@/shared/components/templates/templates";
import { Button } from "@/shared/ui/button";
import { Skeleton } from "@/shared/ui/skeleton";

const DEFAULT_COLUMNS = [
  "short_id",
  "service",
  "external_ref",
  "statuses",
  "eligible",
  "lease",
  "tier",
  "proxy",
] as const;

const COLUMN_OPTIONS = [
  { id: "short_id", label: "Короткий ID" },
  { id: "service", label: "Сервис" },
  { id: "external_ref", label: "External ref" },
  { id: "statuses", label: "Статусы" },
  { id: "eligible", label: "Пригодность" },
  { id: "lease", label: "Аренда" },
  { id: "tier", label: "Уровень" },
  { id: "proxy", label: "Прокси" },
  { id: "tags", label: "Теги и метки" },
  { id: "requirements", label: "Requirements" },
  { id: "last_leased", label: "Последняя аренда" },
  { id: "created", label: "Добавлен" },
  { id: "profile", label: "Профиль" },
] as const;

function optionalBoolean(value: string | undefined): boolean | undefined {
  if (value === "true") return true;
  if (value === "false") return false;
  return undefined;
}

function optionalDate(value: string | undefined): string | undefined {
  if (value === undefined) return undefined;
  const date = new Date(value);
  return Number.isNaN(date.valueOf()) ? undefined : date.toISOString();
}

function apiQuery(search: AccountSearch): AccountQuery {
  const query: AccountQuery = { limit: 50 };
  const assign = <Key extends keyof AccountQuery>(
    key: Key,
    value: AccountQuery[Key] | undefined,
  ) => {
    if (value !== undefined) query[key] = value;
  };
  assign("q", search.q);
  assign("cursor", search.cursor);
  assign("service", search.service);
  assign("lifecycle", search.lifecycle);
  assign("standing", search.standing);
  assign("auth", search.auth);
  assign("availability", search.availability);
  assign("tag", search.tag);
  assign("eligible", optionalBoolean(search.eligible));
  assign("leased", optionalBoolean(search.leased));
  assign("has_override", optionalBoolean(search.hasOverride));
  assign("requirement", search.requirement);
  assign("factor", search.factor);
  assign("factor_state", search.factorState);
  assign("tier", search.tier);
  assign("proxy", search.proxy);
  assign("linked", optionalBoolean(search.linked));
  assign("created_from", optionalDate(search.createdFrom));
  assign("created_to", optionalDate(search.createdTo));
  assign("last_leased_from", optionalDate(search.lastLeasedFrom));
  assign("last_leased_to", optionalDate(search.lastLeasedTo));
  assign("synced_from", optionalDate(search.syncedFrom));
  assign("synced_to", optionalDate(search.syncedTo));
  assign("standing_changed_from", optionalDate(search.standingChangedFrom));
  assign("standing_changed_to", optionalDate(search.standingChangedTo));
  if (search.status === "attention") assign("attention", true);
  else if (search.status?.includes(":") === true) {
    const [region, state] = search.status.split(":", 2);
    if (
      region === "lifecycle" ||
      region === "standing" ||
      region === "auth" ||
      region === "availability"
    ) {
      assign(region, state);
    }
  }
  return query;
}

function accountColumns(): ColumnDef<AccountListItemResponse>[] {
  return [
    { id: "short_id", header: "ID", accessorKey: "short_id" },
    { id: "service", header: "Сервис", accessorKey: "service" },
    { id: "external_ref", header: "External ref", accessorKey: "external_ref" },
    {
      id: "statuses",
      header: "Статусы",
      cell: ({ row }) => (
        <>
          <DomainStatusBadge
            registry={LIFECYCLE_VIEW}
            value={row.original.lifecycle}
          />{" "}
          <DomainStatusBadge
            registry={STANDING_VIEW}
            value={row.original.standing}
          />{" "}
          <DomainStatusBadge
            registry={AUTH_STATE_VIEW}
            value={row.original.auth}
          />{" "}
          <DomainStatusBadge
            registry={AVAILABILITY_VIEW}
            value={row.original.availability}
          />
        </>
      ),
    },
    {
      id: "eligible",
      header: "Пригодность",
      cell: ({ row }) => <EligibilityCell row={row.original} />,
    },
    {
      id: "lease",
      header: "Аренда",
      cell: ({ row }) => <LeaseCell row={row.original} />,
    },
    {
      id: "tier",
      header: "Уровень",
      cell: ({ row }) => row.original.verification_tier ?? "—",
    },
    {
      id: "proxy",
      header: "Прокси",
      cell: ({ row }) => <ProxyCell row={row.original} />,
    },
    {
      id: "tags",
      header: "Теги и метки",
      cell: ({ row }) => <TagsCell row={row.original} />,
    },
    {
      id: "requirements",
      header: "Requirements",
      cell: ({ row }) => row.original.requirements.join(" · ") || "—",
    },
    {
      id: "last_leased",
      header: "Последняя аренда",
      cell: ({ row }) => <DateCell value={row.original.last_leased_at} />,
    },
    {
      id: "created",
      header: "Добавлен",
      cell: ({ row }) => <DateCell value={row.original.created_at} />,
    },
    {
      id: "profile",
      header: "Профиль",
      cell: ({ row }) =>
        Object.entries(row.original.profile)
          .slice(0, 3)
          .map(([key, value]) => `${key}:${String(value)}`)
          .join(" · ") || "—",
    },
  ];
}

export function AccountsPage() {
  const { spaceSlug } = useParams({
    from: "/_authenticated/spaces/$spaceSlug/accounts",
  });
  const search = useSearch({
    from: "/_authenticated/spaces/$spaceSlug/accounts",
  });
  const navigate = useNavigate({ from: "/spaces/$spaceSlug/accounts" });
  const preferences = usePreferences();
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const selectedColumns = useMemo(
    () =>
      new Set(search.columns?.split(",").filter(Boolean) ?? DEFAULT_COLUMNS),
    [search.columns],
  );
  const columns = useMemo(
    () =>
      accountColumns().filter((column) => selectedColumns.has(column.id ?? "")),
    [selectedColumns],
  );
  const queryValues = apiQuery(search);
  const query = useQuery({
    queryKey: ["space", spaceSlug, "accounts", queryValues],
    queryFn: ({ signal }) => fetchAccounts(spaceSlug, queryValues, signal),
    placeholderData: (previous) => previous,
    refetchInterval: POLL_INTERVAL.operational,
  });
  const overview = useQuery({
    queryKey: ["space", spaceSlug, "overview", "all"],
    queryFn: ({ signal }) => fetchSpaceOverview(spaceSlug, undefined, signal),
    staleTime: POLL_INTERVAL.reference,
  });
  const services =
    overview.data?.services.map((service) => service.service) ?? [];

  const patchSearch = (patch: Partial<AccountSearch>) => {
    void navigate({
      search: (previous) => {
        const next: AccountSearch = { ...previous };
        delete next.cursor;
        for (const [key, value] of Object.entries(patch)) {
          if (value === undefined) delete next[key as keyof AccountSearch];
          else Object.assign(next, { [key]: value });
        }
        return next;
      },
    });
  };

  return (
    <ListPage
      eyebrow="Пространство"
      title={`Аккаунты · ${spaceSlug}`}
      description="Безопасная страница с keyset pagination. Секреты и lease token не входят в API."
      actions={
        <AccountColumnPicker
          columns={[...COLUMN_OPTIONS]}
          selected={selectedColumns}
          onChange={(next) =>
            patchSearch({ columns: [...next].sort().join(",") })
          }
        />
      }
    >
      <AccountFilters
        value={search as AccountFilterValue}
        services={services}
        onPatch={(patch) => patchSearch(patch as Partial<AccountSearch>)}
        onReset={() =>
          void navigate({
            search:
              search.columns === undefined ? {} : { columns: search.columns },
          })
        }
      />
      <QueryState<AccountPageResponse>
        query={query}
        skeleton={<Skeleton className="h-96 w-full" />}
        empty={{
          title: "Аккаунты не найдены",
          description: "Измените фильтры или строку поиска.",
        }}
        isEmpty={(data) => data.items.length === 0}
      >
        {(data) => (
          <div className="grid gap-4">
            <AccountListSummary
              selected={selected.size}
              total={data.total_label}
            />
            <DataTable
              columns={columns}
              data={data.items}
              density={preferences.density}
              getRowId={(row) => row.id}
              selectedRowIds={selected}
              onSelectionChange={setSelected}
            />
            <div className="flex items-center justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                disabled={search.cursor === undefined}
                onClick={() => window.history.back()}
              >
                Назад
              </Button>
              <Button
                type="button"
                disabled={data.next_cursor === null}
                onClick={() => {
                  if (data.next_cursor !== null)
                    patchSearch({ cursor: data.next_cursor });
                }}
              >
                Далее
              </Button>
            </div>
          </div>
        )}
      </QueryState>
    </ListPage>
  );
}

