import { useEffect, useState, type FormEvent } from "react";

import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/ui/select";

export interface AccountFilterValue {
  auth?: string;
  availability?: string;
  createdFrom?: string;
  createdTo?: string;
  eligible?: string;
  factor?: string;
  factorState?: string;
  hasOverride?: string;
  lastLeasedFrom?: string;
  lastLeasedTo?: string;
  leased?: string;
  lifecycle?: string;
  linked?: string;
  proxy?: string;
  q?: string;
  requirement?: string;
  service?: string;
  standing?: string;
  standingChangedFrom?: string;
  standingChangedTo?: string;
  syncedFrom?: string;
  syncedTo?: string;
  tag?: string;
  tier?: string;
}

interface Option {
  label: string;
  value: string;
}

const LIFECYCLE: Option[] = [
  { label: "Подготовка", value: "provisioning" },
  { label: "Готов", value: "ready" },
  { label: "Выведен", value: "retired" },
];
const STANDING: Option[] = [
  "good",
  "limited",
  "frozen",
  "appealing",
  "banned",
  "deleted",
].map((value) => ({ label: value, value }));
const AUTH: Option[] = [
  "no_session",
  "logging_in",
  "challenge",
  "authenticated",
  "session_invalid",
].map((value) => ({ label: value, value }));
const AVAILABILITY: Option[] = [
  "available",
  "paused",
  "cooling",
  "quarantined",
].map((value) => ({ label: value, value }));
const BOOLEAN: Option[] = [
  { label: "Да", value: "true" },
  { label: "Нет", value: "false" },
];

function FilterSelect({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  options: Option[];
  value?: string | undefined;
  onChange: (value: string | undefined) => void;
}) {
  return (
    <Select
      value={value ?? "all"}
      onValueChange={(next) => onChange(next === "all" ? undefined : next)}
    >
      <SelectTrigger aria-label={label}>
        <SelectValue placeholder={label} />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="all">{label}: все</SelectItem>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

function TextFilter({
  label,
  value,
  onChange,
  type = "text",
}: {
  label: string;
  value?: string | undefined;
  onChange: (value: string | undefined) => void;
  type?: "datetime-local" | "text";
}) {
  return (
    <label className="grid gap-1 text-sm font-medium">
      {label}
      <Input
        type={type}
        value={value ?? ""}
        onChange={(event) => onChange(event.target.value || undefined)}
      />
    </label>
  );
}

export function AccountFilters({
  value,
  services,
  onPatch,
  onReset,
}: {
  value: AccountFilterValue;
  services: string[];
  onPatch: (patch: Partial<AccountFilterValue>) => void;
  onReset: () => void;
}) {
  const [draft, setDraft] = useState(value.q ?? "");
  useEffect(() => setDraft(value.q ?? ""), [value.q]);
  const patch = (key: keyof AccountFilterValue, next: string | undefined) =>
    onPatch({ [key]: next });

  const submit = (event: FormEvent) => {
    event.preventDefault();
    patch("q", draft || undefined);
  };

  return (
    <div className="grid gap-4">
      <form className="flex flex-col gap-2 sm:flex-row" onSubmit={submit}>
        <Input
          aria-label="Поиск аккаунтов"
          placeholder="service:telegram standing:banned country:UA olena"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
        />
        <Button type="submit">Найти</Button>
        <Button type="button" variant="outline" onClick={onReset}>
          Сбросить
        </Button>
      </form>
      <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
        <FilterSelect
          label="Сервис"
          options={services.map((service) => ({
            label: service,
            value: service,
          }))}
          value={value.service}
          onChange={(next) => patch("service", next)}
        />
        <FilterSelect
          label="Lifecycle"
          options={LIFECYCLE}
          value={value.lifecycle}
          onChange={(next) => patch("lifecycle", next)}
        />
        <FilterSelect
          label="Standing"
          options={STANDING}
          value={value.standing}
          onChange={(next) => patch("standing", next)}
        />
        <FilterSelect
          label="Auth"
          options={AUTH}
          value={value.auth}
          onChange={(next) => patch("auth", next)}
        />
        <FilterSelect
          label="Availability"
          options={AVAILABILITY}
          value={value.availability}
          onChange={(next) => patch("availability", next)}
        />
        <FilterSelect
          label="Пригоден"
          options={BOOLEAN}
          value={value.eligible}
          onChange={(next) => patch("eligible", next)}
        />
        <FilterSelect
          label="В аренде"
          options={BOOLEAN}
          value={value.leased}
          onChange={(next) => patch("leased", next)}
        />
        <FilterSelect
          label="Есть override"
          options={BOOLEAN}
          value={value.hasOverride}
          onChange={(next) => patch("hasOverride", next)}
        />
      </div>
      <details className="rounded-md border p-3">
        <summary className="cursor-pointer text-sm font-medium">
          Расширенные фильтры
        </summary>
        <div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          {(
            [
              ["tag", "Тег"],
              ["requirement", "Requirement"],
              ["factor", "Фактор"],
              ["factorState", "Состояние фактора"],
              ["tier", "Уровень верификации"],
              ["proxy", "Прокси: id или хост"],
            ] as const
          ).map(([key, label]) => (
            <TextFilter
              key={key}
              label={label}
              value={value[key]}
              onChange={(next) => patch(key, next)}
            />
          ))}
          <FilterSelect
            label="Есть связь"
            options={BOOLEAN}
            value={value.linked}
            onChange={(next) => patch("linked", next)}
          />
          {(
            [
              ["createdFrom", "Добавлен с"],
              ["createdTo", "Добавлен до"],
              ["lastLeasedFrom", "Последняя аренда с"],
              ["lastLeasedTo", "Последняя аренда до"],
              ["syncedFrom", "Сверен с"],
              ["syncedTo", "Сверен до"],
              ["standingChangedFrom", "Standing изменён с"],
              ["standingChangedTo", "Standing изменён до"],
            ] as const
          ).map(([key, label]) => (
            <TextFilter
              key={key}
              label={label}
              type="datetime-local"
              value={value[key]}
              onChange={(next) => patch(key, next)}
            />
          ))}
        </div>
      </details>
    </div>
  );
}

export function AccountColumnPicker({
  columns,
  selected,
  onChange,
}: {
  columns: Array<{ id: string; label: string }>;
  selected: ReadonlySet<string>;
  onChange: (selected: ReadonlySet<string>) => void;
}) {
  return (
    <details className="relative">
      <summary className="cursor-pointer text-sm font-medium">Колонки</summary>
      <div className="bg-popover absolute right-0 z-10 mt-2 grid min-w-56 gap-2 rounded-md border p-3 shadow-md">
        {columns.map((column) => (
          <label className="flex items-center gap-2 text-sm" key={column.id}>
            <input
              checked={selected.has(column.id)}
              className="accent-primary size-4"
              type="checkbox"
              onChange={(event) => {
                const next = new Set(selected);
                if (event.target.checked) next.add(column.id);
                else next.delete(column.id);
                onChange(next);
              }}
            />
            {column.label}
          </label>
        ))}
      </div>
    </details>
  );
}

import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  type ColumnDef,
} from "@tanstack/react-table";

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/ui/table";

export interface DataTableProps<TData> {
  columns: ColumnDef<TData>[];
  data: TData[];
  density?: "compact" | "default";
  getRowId?: (row: TData) => string;
  onSelectionChange?: (selected: ReadonlySet<string>) => void;
  selectedRowIds?: ReadonlySet<string>;
}

export function DataTable<TData>({
  columns,
  data,
  density = "default",
  getRowId,
  onSelectionChange,
  selectedRowIds = new Set<string>(),
}: DataTableProps<TData>) {
  const table = useReactTable({
    columns,
    data,
    getCoreRowModel: getCoreRowModel(),
    ...(getRowId === undefined ? {} : { getRowId }),
  });
  const visibleIds = table.getRowModel().rows.map((row) => row.id);
  const allVisibleSelected =
    visibleIds.length > 0 && visibleIds.every((id) => selectedRowIds.has(id));

  const updateSelection = (id: string, selected: boolean) => {
    const next = new Set(selectedRowIds);
    if (selected) next.add(id);
    else next.delete(id);
    onSelectionChange?.(next);
  };

  return (
    <div className="overflow-hidden rounded-lg border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {onSelectionChange === undefined ? null : (
                <TableHead className="w-10">
                  <input
                    aria-label="Выбрать все строки на странице"
                    checked={allVisibleSelected}
                    className="accent-primary size-4"
                    type="checkbox"
                    onChange={(event) => {
                      const next = new Set(selectedRowIds);
                      for (const id of visibleIds) {
                        if (event.target.checked) next.add(id);
                        else next.delete(id);
                      }
                      onSelectionChange(next);
                    }}
                  />
                </TableHead>
              )}
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id}>
                  {header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow
              data-state={selectedRowIds.has(row.id) ? "selected" : undefined}
              key={row.id}
            >
              {onSelectionChange === undefined ? null : (
                <TableCell>
                  <input
                    aria-label={`Выбрать строку ${row.id}`}
                    checked={selectedRowIds.has(row.id)}
                    className="accent-primary size-4"
                    type="checkbox"
                    onChange={(event) =>
                      updateSelection(row.id, event.target.checked)
                    }
                  />
                </TableCell>
              )}
              {row.getVisibleCells().map((cell) => (
                <TableCell
                  className={density === "compact" ? "py-1" : "py-2"}
                  key={cell.id}
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

export function NumberCell({ value }: { value: number }) {
  return (
    <span className="block text-right font-mono tabular-nums">
      {new Intl.NumberFormat("ru-RU").format(value)}
    </span>
  );
}
